
import React, { useState, useEffect } from "react";


import {  useNavigate } from "react-router-dom";
import { updStore, getStore, gen16CodeId, qryKClient,  copyToClipboard, parseDate,  getExtFileType, b64toUrl, CapitalizeString } from "../../../stores/Utils";

import { handleFetchImage, handleFetchImageComp, getFNMLabels } from "../services/customer_fetch_service";
import DarkCard from "./DarkCard";





const InformationView  = ({  }) => {
	const [, set_obs] = useState(1);
	
	const navigate = useNavigate();
	let clientItm = getStore(qryKClient());

	
	useEffect(() => {
		getStore(qryKClient())?.imagePath && openImage();
	},[clientItm?.movementId]);



	const updObs  =  (v)  => {
		set_obs(gen16CodeId());
	};


	

	const validateImage = (result) => {
		
		var i = new Image();	
		i.onload = function(){
			let dmzImg = {
				oh: i.height,
				ow: i.width,
				h: i.height,
				w: i.width,
			}
			updStore( "preview_mov_dmz",dmzImg);
			updObs()
		};
		if(result){
			i.src = result;
		}
	}	

	const open2312312Image =  () => {
		let extTp = getExtFileType(getStore(qryKClient()).imagePath);
		handleFetchImage(getStore("profileUser")?.businessId,getStore(qryKClient()).imagePath, (v)=>openImageCb(v,extTp));
	}

  

  
	const Image2Resize = async () => {
		let imagePathWp = getStore(qryKClient()).imagePath;
		handleFetchImage(imagePathWp, (v)=>{
			handleFetchImageComp(v,imagePathWp);
			let extTp = getExtFileType(imagePathWp);
			openImageCb(v, extTp);
		});
	}


	

	

	const open2ImageCb = async (v, ext, imagePathWp) => {
		if(v){
			openImageCb(v, ext, imagePathWp);
		}
		else{
			Image2Resize();
		}
	}
	

	const openImage =  () => {
		let imagePathWp = getStore(qryKClient()).imagePath;
		imagePathWp = imagePathWp.split(".png")[0]+".webp";
		let extTp = getExtFileType(imagePathWp);
		handleFetchImage(imagePathWp, (v)=>open2ImageCb(v,extTp,imagePathWp));
	}


	const openImageCb = async (v,ext, imagePathWp) => {
		var blob = await b64toUrl(v, ext);
		updStore("image_fileName",imagePathWp);
		updStore("image_url_mov",v);
		updStore("image_preview_mov",blob);
		validateImage(blob);
	}



	let amount = clientItm?.amount? "$" + (clientItm?.amount*1).toFixed(2) : "$0.00";
	let typeColor = clientItm?.movementType === "expense"?"var(--primary-red--color-f7)":"var(--primary-blue--backg-30)";


	return (
		<div className={clientItm?.movementType}>
			<div style={{marginLeft: 6, padding: "10px 0 0 4px"}}>
				
				
				<div className="_dsplFlx  spaceAround flxWrp" >
					<DarkCard
						icon={"calendar"}
						iconColor={typeColor}
						label={getFNMLabels(55)}
						value={clientItm?.date? parseDate(clientItm?.date*1) : ""} 
						handleClick={()=>{}}
					/>
					
					<DarkCard
						icon={"groups"}
						iconColor={typeColor}
						label={getFNMLabels(54)}
						value={clientItm?.categoryInfo?.name}
						handleClick={()=>{}}
					/>
				</div>
				
				<div className="_dsplFlx  spaceAround flxWrp" >
					<div className="client_item_box gWXAaj jlytmu "  style={{marginBottom: 14}}>
						<div className="title_cardheader fS16">
							{getFNMLabels(50)}
						</div>
						<div className="title_cardheader l300 ">
							{clientItm?.title}
						</div>
					</div>

					<div className="client_item_box gWXAaj jlytmu "  style={{marginBottom: 14}}>
						<div className="title_cardheader fS16">
							{getFNMLabels(51)}
						</div>
						<div className="title_cardheader l300 ">
							{amount}
						</div>
					</div>
					
					<div className="client_item_box gWXAaj jlytmu"  style={{marginBottom: 14}}>
						<div className="title_cardheader fS16">
							{getFNMLabels(52)}
						</div>
						<div className="title_cardheader l300 ">
							{clientItm?.document}
						</div>
					</div>

					<div className="client_item_box gWXAaj jlytmu"  style={{marginBottom: 14}}>
						<div className="title_cardheader fS16">
							{getFNMLabels(53)}
						</div>
						<div className="title_cardheader l300 ">
							{clientItm?.description}
						</div>
					</div>

				</div>
				<div className="imagePreview"  style={{   }}>
				
					{getStore("preview_mov_dmz")?
					<SVG_img image={getStore("image_preview_mov")}/>:null}
				</div>

			</div>
		</div>
          
	)
}








export default InformationView;






